(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const s = window.__toolboxStore;
  const out = {};

  for (let i = 0; i < 40; i++) {
    await sleep(500);
    if (document.querySelector('.pj-title') || document.querySelector('.tb-error')) break;
  }
  out.opened = document.querySelector('.pj-title')?.textContent || null;
  out.diffBadge = document.querySelector('.pj-diff')?.textContent || null;
  out.tabs = [...document.querySelectorAll('.pc-tab')].map((b) => b.textContent.trim());

  const tab = (name) => [...document.querySelectorAll('.pc-tab')].find((b) => b.textContent.includes(name));

  // 程序代码
  out.codeName = document.querySelector('.pc-item-name')?.textContent || null;
  out.codeChinese = (document.querySelector('.pc-code')?.textContent || '').includes('让 LED 闪起来');

  // 接线表
  tab('接线表')?.click();
  await sleep(800);
  out.pinRows = [...document.querySelectorAll('.pc-table tbody tr')].map((tr) => [...tr.querySelectorAll('input')].map((i) => i.value).join(' | '));

  // 调试记录
  tab('调试记录')?.click();
  await sleep(800);
  out.debugProblems = [...document.querySelectorAll('.pc-debug-problem')].map((e) => e.textContent);
  out.debugSolutions = [...document.querySelectorAll('.pc-debug-solution')].map((e) => e.textContent.slice(0, 24));

  // 开发环境
  tab('开发环境')?.click();
  await sleep(800);
  out.envText = (document.querySelector('.pc-textarea')?.value || '').slice(0, 40);

  const projects = await s.listProjects();
  const p = projects.find((x) => x.name.includes('四件套'));
  const bundle = await s.getProject(p.id);
  out.stored = {
    difficulty: bundle.project.difficulty,
    codeNote: (bundle.project.codeNote || '').slice(0, 20),
    code: bundle.codeFiles.map((c) => ({ n: c.name, g: c.group })),
    pins: bundle.pinRows.map((r) => `${r.module}/${r.pin}→${r.boardPin}`),
    debugs: bundle.debugNotes.map((d) => d.problem),
  };
  return JSON.stringify(out);
})()
